
'use strict';
const IDIOMS=[
 {name:'Dalam Tangan',ride:'Jatuhkan Botol',icon:'🎯',meaning:'Sudah pasti diperoleh atau dikuasai.',story:['Hadiah pertandingan itu sudah dijanjikan kepada kumpulan Amir.','Guru mengesahkan bahawa kumpulan Amir telah menang.','Amir tersenyum kerana hadiah itu sudah dalam tangan.','Mereka mengambil hadiah selepas majlis tamat.'],pictures:['🏆','👩‍🏫','😊','🎁'],q:['Apakah yang dijanjikan?','Apakah yang guru sahkan?','Mengapakah Amir yakin?','Apakah yang berlaku akhirnya?']},
 {name:'Ambil Hati',ride:'Kedai Cenderamata',icon:'🎁',meaning:'Menyenangkan atau menggembirakan hati seseorang.',story:['Aina melihat ibunya kelihatan penat.','Aina memilih hadiah kecil di kedai cenderamata.','Aina memberikan hadiah itu untuk mengambil hati ibunya.','Ibunya tersenyum dan mengucapkan terima kasih.'],pictures:['👩','🛍️','🎀','🥰'],q:['Bagaimanakah keadaan ibu?','Apakah yang Aina pilih?','Mengapakah Aina memberi hadiah?','Bagaimanakah reaksi ibu?']},
 {name:'Anak Emas',ride:'Memanah',icon:'🏹',meaning:'Orang yang paling disayangi atau diberi keutamaan.',story:['Jurulatih selalu memberikan perhatian istimewa kepada Faris.','Faris sering dipilih untuk membantu jurulatih.','Rakan-rakan menggelarnya anak emas jurulatih.','Jurulatih mengingatkan semua murid bahawa mereka tetap dihargai.'],pictures:['🏹','👨‍🏫','⭐','🤝'],q:['Siapakah yang mendapat perhatian?','Apakah keutamaan yang diberikan?','Apakah gelaran Faris?','Apakah pesanan jurulatih?']},
 {name:'Air Muka',ride:'Swing Ride',icon:'🎠',meaning:'Raut atau ekspresi wajah seseorang.',story:['Lina kelihatan risau sebelum menaiki buaian berpusing.','Kawannya menenangkan Lina dengan kata-kata yang baik.','Air muka Lina berubah apabila dia mula berasa yakin.','Lina tersenyum selepas menikmati permainan itu.'],pictures:['😟','🤗','😌','😁'],q:['Bagaimanakah wajah Lina pada awalnya?','Siapakah yang menenangkannya?','Bagaimanakah air mukanya berubah?','Apakah perasaannya akhirnya?']},
 {name:'Mandi Peluh',ride:'Roller Coaster',icon:'🎢',meaning:'Berpeluh dengan banyaknya.',story:['Petugas taman tema bekerja keras membersihkan kawasan permainan.','Mereka mengangkat peralatan dan menyusun kerusi.','Mereka mandi peluh selepas bekerja di bawah cuaca panas.','Mereka berehat dan minum air setelah tugas selesai.'],pictures:['🧹','🪑','🥵','🥤'],q:['Apakah tugas petugas?','Apakah kerja yang dilakukan?','Mengapakah mereka mandi peluh?','Apakah yang mereka lakukan selepas itu?']},
 {name:'Cakap Besar',ride:'Pirate Ship',icon:'🏴‍☠️',meaning:'Bercakap dengan sombong atau bermegah-megah.',story:['Hakim bermegah bahawa dia langsung tidak takut menaiki kapal lanun.','Dia terus bercakap besar di hadapan rakan-rakannya.','Apabila kapal berayun tinggi, Hakim mula berasa takut.','Hakim sedar bahawa dia tidak patut bermegah-megah.'],pictures:['😎','🗣️','😨','🙂'],q:['Apakah yang Hakim dakwa?','Bagaimanakah dia bercakap?','Apakah yang berlaku di atas kapal?','Apakah pengajaran untuk Hakim?']}
];
const COTTON=[{icon:'🍥',name:'Pusaran Pelangi'},{icon:'💗',name:'Hati Merah Jambu'},{icon:'⭐',name:'Bintang Emas'},{icon:'☁️',name:'Awan Biru'},{icon:'🌸',name:'Bunga Sakura'},{icon:'🌈',name:'Pelangi Ajaib'}];
const ANIMALS={panda:'🐼',harimau:'🐯',kucing:'🐱',ulat:'🐛'};
const DEFAULT_PREF={font:'normal',fontFamily:'normal',wide:false,contrast:false,focus:false,reduce:false};
let pref=SimpulBackend.read('simpulloka_pref')||DEFAULT_PREF;
let session=SimpulBackend.read(SimpulBackend.sessionKey);
let reflection=null,reflectionFeeling='',reflectionLearning='',recoveryDone=false,reinforcementDone=false,progress={},page='home',loka=0,stage=0,order=[],selected=-1,attempts=0,hints=0,correct=false,simpul=false,storyDone=false,storyFrame=0,showAll=false,showHelp=false,talking=false,teacherPass='',teacherData=null,teacherSelected='',teacherLoka=1,teacherAssessment=null;
const el=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(msg){const t=el('toast');t.textContent=msg;t.classList.remove('hidden');clearTimeout(window._toastTimer);window._toastTimer=setTimeout(()=>t.classList.add('hidden'),4500);}
function call(fn,...args){return SimpulBackend.call(fn,...args);}
function setPref(k,v){pref[k]=v;localStorage.setItem('simpulloka_pref',JSON.stringify(pref));applyPref();}
function applyPref(){document.body.classList.remove('bigtext','extrabig','wideletters','contrast','focus','reduce','font-andika');if(pref.font!=='normal')document.body.classList.add(pref.font);if(pref.fontFamily==='andika')document.body.classList.add('font-andika');if(el('fontFamily'))el('fontFamily').value=pref.fontFamily||'normal';if(pref.wide)document.body.classList.add('wideletters');['contrast','focus','reduce'].forEach(x=>{if(pref[x])document.body.classList.add(x);});if(el('fontSize'))el('fontSize').value=pref.font;['wide','contrast','focus','reduce'].forEach(x=>{if(el(x))el(x).checked=!!pref[x];});}
function toggleAccess(){el('accessPanel').classList.toggle('hidden');}
function speech(text){if(!('speechSynthesis'in window)){notify('Audio bacaan tidak disokong oleh pelayar ini.');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='ms-MY';u.rate=.82;speechSynthesis.speak(u);}
function navTo(p){if(p==='story'&&(!correct||!simpul)){blockedNext('Selesaikan CABARAN dan SIMPUL sebelum masuk Studio Cerita.');return;}if(talking)talking=false;page=p;render();window.scrollTo({top:0,behavior:'smooth'});}
function navHtml(){const links=[['home','🏰 Gerbang'],['map','📖 Peta Ilmu'],['wheel','🎡 Roda Ferris'],['passport','📔 Pasport'],['reflection','🌈 Refleksi'],['recovery','🌱 Pemulihan'],['reinforcement','🚀 Pengukuhan'],['teacher','👩‍🏫 Sudut Cikgu']];el('nav').innerHTML=links.map(([p,t])=>`<button class="${page===p?'on':''}" onclick="navTo('${p}')">${t}</button>`).join('');}
function render(){navHtml();const root=el('app');const views={home:homeHtml,map:mapHtml,wheel:wheelHtml,loka:lokaHtml,story:storyHtml,passport:passportHtml,reflection:reflectionHtml,recovery:recoveryHtml,reinforcement:reinforcementHtml,teacher:teacherHtml};root.innerHTML=(views[page]||homeHtml)();applyPref();}
function homeHtml(){return `<section class="panel hero"><div class="eyebrow">Selamat datang ke taman tema bahasa!</div><h1>🏰 SimpulLoka 🎡</h1><p>Enam Loka, Enam Simpulan, Seribu Cerita!</p><div class="scene"><div class="ride-art">🎡 🎠 🎢</div></div><p class="small" id="storageNotice">${SimpulBackend.mode==='local'?'Mod setempat: kemajuan disimpan pada pelayar ini sahaja. Sudut Cikgu memerlukan sambungan backend.':'Mod sekolah: rekod disimpan melalui sambungan backend.'}</p><p>Hai, anak-anak! Mari belajar simpulan bahasa melalui pengembaraan yang menyeronokkan!</p><div class="tile"><h2>🍭 Misi Pengembara SimpulLoka</h2><p><strong>Kumpulkan 6 cop SimpulLoka dan dapatkan 6 gula kapas dengan bentuk istimewa!</strong></p><div class="giftline">${COTTON.map(x=>`<div class="gift"><div class="symbol">${x.icon}</div><small>${x.name}</small></div>`).join('')}</div></div>${session?`<div class="tile"><h3>🎟️ Selamat kembali, ${esc(session.nickname)}!</h3><p>Kelas: ${esc(session.kelas||'Belum dinyatakan')}</p><p>${ANIMALS[session.avatar]||'🐼'} ID Tiket: ${esc(session.studentId)}</p><button onclick="navTo('map')">Teruskan Pengembaraan →</button></div>`:`<div class="tile" style="max-width:540px;margin:0 auto"><h2>🎟️ Tiket Pengembaraan</h2><label for="nickname">Nama panggilan</label><input id="nickname" class="field" maxlength="30" placeholder="Contoh: Aina" autocomplete="off"><label for="kelas">Kelas</label><input id="kelas" class="field" maxlength="40" placeholder="Contoh: 3 Bestari" autocomplete="off" required><label for="animal">Pilih avatar pembantu</label><select id="animal" class="field"><option value="panda">🐼 Panda</option><option value="harimau">🐯 Harimau</option><option value="kucing">🐱 Kucing</option><option value="ulat">🐛 Ulat</option></select><button onclick="register()">Dapatkan Tiket ✨</button><p class="small muted">Tidak perlu nama penuh. Simpan tiket pada pelayar yang sama untuk menyambung kemajuan.</p></div>`}</section>`;}
async function register(){const name=el('nickname').value,kelas=el('kelas').value.trim(),avatar=el('animal').value;if(name.trim().length<2){notify('Sila masukkan nama panggilan sekurang-kurangnya dua aksara.');return;}if(kelas.length<2){notify('Sila masukkan kelas.');return;}try{const s=await call('createStudent',name,avatar,kelas);session={studentId:s.studentId,token:s.token,nickname:s.nickname,kelas:s.kelas,avatar:s.avatar};localStorage.setItem(SimpulBackend.sessionKey,JSON.stringify(session));notify('Tiket berjaya disediakan!');navTo('map');}catch(e){notify(e.message);}}
function mapHtml(){return `<section class="panel"><div class="eyebrow">Peta Ilmu Simpulan Bahasa</div><h1>📖 Apakah Simpulan Bahasa?</h1><p>Simpulan bahasa ialah gabungan dua perkataan atau lebih yang mempunyai makna khusus dan tidak semestinya sama dengan makna perkataan secara langsung.</p><div class="scene"><div class="ride-art">📜 🔎 📚</div></div><div class="btnrow"><button onclick="speech('Simpulan bahasa ialah ungkapan yang mempunyai makna khusus. Mari lihat contoh simpulan bahasa.')">🔊 Dengar Penerangan</button><button class="secondary" onclick="navTo('wheel')">Ke Roda Ferris →</button></div><h2>🔎 Klik objek untuk meneroka contoh</h2><div class="grid">${IDIOMS.map((d,i)=>`<button class="tile" style="color:#284d40" onclick="openDefinition(${i})"><span class="emoji">${d.icon}</span><h3>${d.name}</h3><span class="badge">Buka maksud</span></button>`).join('')}</div><div class="hint" id="definition" aria-live="polite">Pilih mana-mana kad untuk mengetahui maksud simpulan bahasa.</div><h2>🧩 Kuiz Pengenalan</h2><p>Apakah maksud <strong>ambil hati</strong>?</p><div class="btnrow"><button class="secondary" onclick="notify('Belum tepat. Cuba fikirkan perasaan seseorang.')">Mengambil organ hati</button><button onclick="notify('Betul! Ambil hati bermaksud menggembirakan hati seseorang.')">Menggembirakan seseorang</button></div></section>`;}
function speakDefinition(i){speech(IDIOMS[i].name+'. '+IDIOMS[i].meaning);}
function speakLokaStory(){speech(IDIOMS[loka].story[0]);}
function speakLokaMeaning(){speech(IDIOMS[loka].name+'. '+IDIOMS[loka].meaning);}
function speakFrameQuestion(i){speech(IDIOMS[loka].q[i]);}
function openDefinition(i){const d=IDIOMS[i];el('definition').innerHTML=`<strong>${d.name}</strong><p>${d.meaning}</p><button onclick="speakDefinition(${i})">🔊 Dengar maksud</button>`;}
function wheelHtml(){return `<section class="panel"><div class="eyebrow">Pilih Pengembaraan</div><h1 style="text-align:center">🎡 Roda Ferris SimpulLoka</h1><p style="text-align:center">Klik gondola atau kad Loka untuk memulakan pengembaraan.</p><div class="wheel" aria-label="Roda Ferris dengan enam gondola">${IDIOMS.map((d,i)=>`<button class="gondola g${i+1}" onclick="enterLoka(${i})"><span>${d.icon}</span>${d.name}</button>`).join('')}</div><div class="grid">${IDIOMS.map((d,i)=>`<button class="tile" style="color:#284d40" onclick="enterLoka(${i})"><span class="emoji">${d.icon}</span><h3>Loka ${i+1}</h3><strong>${d.name}</strong><p class="small">${d.ride}</p><span class="badge">${progress[i+1]?.completed?'✓ Cop diperoleh':'Belum selesai'}</span></button>`).join('')}</div></section>`;}
function enterLoka(i){if(!session){notify('Dapatkan Tiket Pengembaraan dahulu.');navTo('home');return;}loka=i;stage=0;order=[];selected=-1;const p=progress[i+1]||{};attempts=Number(p.attempts)||0;hints=Number(p.hintLevel)||0;correct=!!p.gameCorrect;simpul=!!p.simpulDone;storyDone=!!p.storyDone;navTo('loka');}
function lokaHtml(){const d=IDIOMS[loka];const stages=['LIHAT','TAFSIR','CABARAN','SIMPUL','CERITA'];return `<section class="panel"><div class="eyebrow">Loka ${loka+1} • ${d.ride}</div><h1>${d.icon} ${d.name}</h1><div class="steps">${stages.map((s,i)=>`<button class="${stage===i?'current':''}" onclick="goStage(${i})">${i+1}. ${s}</button>`).join('')}</div>${stage===0?`<div class="scene"><div class="ride-art">${d.icon} 🧒 🌳</div></div><h2>👀 LIHAT — Situasi Cerita</h2><p>Perhatikan situasi yang berkaitan dengan <strong>${d.name}</strong>. Cerita bermula dengan: ${esc(d.story[0])}</p><button class="secondary" onclick="speakLokaStory()">🔊 Dengar cerita</button>`:stage===1?`<div class="scene"><div class="ride-art">${d.icon} 💡</div></div><h2>📖 TAFSIR — Kenali Makna</h2><div class="hint"><strong>${d.name}</strong><p>${d.meaning}</p></div><button class="secondary" onclick="speakLokaMeaning()">🔊 Dengar maksud</button>`:stage===2?gameHtml(d):stage===3?`<h2>🧠 SIMPUL — Kukuhkan Kefahaman</h2><div class="scene"><div class="ride-art">📖 ✨</div></div><p>Hari ini saya belajar bahawa <strong>${d.name}</strong> bermaksud <strong>${d.meaning}</strong></p><p>Fikirkan satu situasi lain yang sesuai menggunakan simpulan bahasa ini.</p><button class="secondary" onclick="speakLokaMeaning()">🔊 Dengar semula</button><div class="btnrow"><button onclick="markSimpul()">${simpul?'✓ Sudah Difahami':'Saya Sudah Faham ✓'}</button></div>`:`<h2>🎬 CERITA — Studio Avatar</h2><p>Ceritakan semula berdasarkan empat gambar bersiri. Murid boleh menggunakan soalan atau dialog sebagai bantuan pilihan.</p><button id="storyEntry" onclick="navTo('story')">Masuk Studio Cerita →</button>`}<div class="btnrow"><button class="secondary" onclick="stage===0?navTo('wheel'):goStage(stage-1)">← Kembali</button><button onclick="nextStage()" id="nextStageButton">Seterusnya →</button></div></section>`;}
function blockedNext(message){notify(message);const btn=el('nextStageButton')||el('storyEntry');if(btn){btn.classList.remove('needs-work');void btn.offsetWidth;btn.classList.add('needs-work');setTimeout(()=>btn.classList.remove('needs-work'),900);}if(!pref.reduce&&navigator.vibrate)navigator.vibrate(90);}
function canGoStage(n){if(n>=3&&!correct){blockedNext('Sila lengkapkan CABARAN dengan betul sebelum meneruskan.');return false;}if(n>=4&&!simpul){blockedNext('Sila selesaikan fasa SIMPUL dahulu.');return false;}return true;}
function goStage(n){if(!canGoStage(n))return;stage=n;render();}
function nextStage(){if(stage===4){navTo('story');return;}goStage(stage+1);}
function gameHtml(d){const shuffle=[2,0,3,1];const remaining=shuffle.filter(i=>!order.includes(i));return `<h2>🎯 CABARAN — Susun Empat Ayat</h2><p>Pilih kad cerita di sebelah kiri, kemudian tekan petak bernombor. Pada telefon, gunakan kaedah klik. Kad juga boleh diseret pada komputer.</p><div class="scene"><div id="rideAnimation" class="ride-art ride${loka+1} ${correct?'win':''}">${d.icon}</div></div><div class="two"><div><h3>🃏 Kad Cerita</h3>${remaining.length?remaining.map(i=>`<button class="storycard ${selected===i?'selected':''}" draggable="true" ondragstart="dragCard(event,${i})" onclick="selectCard(${i})">${esc(d.story[i])}</button>`).join(''):'<p>Semua kad telah diletakkan.</p>'}</div><div><h3>🔢 Susunan Cerita</h3>${[0,1,2,3].map(j=>`<div class="slot" ondragover="event.preventDefault()" ondrop="dropCard(event,${j})"><strong>${j+1}.</strong>${order[j]!==undefined?`<span>${esc(d.story[order[j]])}</span><button class="secondary" onclick="removeSlot(${j})" aria-label="Alih kad">✕</button>`:`<button class="secondary" onclick="putCard(${j})">Letak kad +</button>`}</div>`).join('')}</div></div><div class="btnrow"><button onclick="checkOrder()" ${order.length!==4||correct?'disabled':''}>✓ Semak Susunan</button><button class="secondary" onclick="hint()">💡 Petunjuk</button><button class="secondary" onclick="resetOrder()">↺ Susun Semula</button></div><div class="hint" id="gameFeedback">${correct?'🌟 Anda sudah menyelesaikan permainan ini!':hints?'Anda boleh cuba lagi. Petunjuk telah digunakan: '+hints:'Susun kad dan tekan Semak Susunan.'}</div><p class="small muted">Cubaan: ${attempts} · Tahap bantuan: ${hints}. Jawapan betul akan menggerakkan tarikan ${d.ride}.</p>`;}
function selectCard(i){if(correct){notify('CABARAN telah selesai. Teruskan ke SIMPUL.');return;}selected=i;render();}function putCard(slot){if(correct)return;if(selected<0){notify('Pilih kad ayat dahulu.');return;}if(order[slot]!==undefined){notify('Kosongkan petak ini dahulu.');return;}order[slot]=selected;selected=-1;render();}function removeSlot(slot){if(correct)return;order.splice(slot,1);render();}function dragCard(e,i){e.dataTransfer.setData('text/plain',String(i));}function dropCard(e,slot){e.preventDefault();const i=Number(e.dataTransfer.getData('text/plain'));if(!Number.isInteger(i)||i<0||i>3)return;selected=i;putCard(slot);}function resetOrder(){if(correct)return;order=[];selected=-1;render();}
async function persist(){if(!session)return;try{const p=await call('saveProgress',session.studentId,session.token,loka+1,attempts,hints,correct,simpul,storyDone);progress[loka+1]=p;return p;}catch(e){notify('Kemajuan belum dapat disimpan: '+e.message);return null;}}
async function checkOrder(){if(correct||order.length!==4)return;attempts++;if(order.every((v,i)=>v===i)){correct=true;render();el('rideAnimation')?.classList.add('win');el('gameFeedback').textContent='🎉 Betul! Semua ayat tersusun dengan tepat. Tarikan bergerak!';notify('Tahniah! Susunan cerita betul.');}else{hints=Math.max(hints,Math.min(3,attempts));render();el('gameFeedback').textContent=attempts===1?'Cuba lagi. Cari ayat yang memperkenalkan watak dan situasi.':attempts===2?'Petunjuk: Cari peristiwa awal, kemudian peristiwa yang menggunakan simpulan bahasa.':'Petunjuk: Perhatikan urutan permulaan → tindakan → penggunaan simpulan bahasa → penutup.';}await persist();}
async function hint(){hints=Math.min(3,hints+1);const msgs=['','Petunjuk 1: Cari ayat yang memperkenalkan watak.','Petunjuk 2: Perhatikan tindakan sebelum simpulan bahasa digunakan.','Petunjuk 3: Susun cerita mengikut permulaan, perkembangan, penggunaan simpulan bahasa dan penutup.'];el('gameFeedback').textContent=msgs[hints];await persist();}
async function markSimpul(){simpul=true;await persist();notify('Fasa SIMPUL selesai!');render();}
function storyHtml(){const d=IDIOMS[loka];return `<section class="panel"><div class="eyebrow">Loka ${loka+1} • ${d.name}</div><h1>🎬 Studio Cerita</h1><p>Gunakan gambar untuk bercerita dengan ayat sendiri. <strong>Rakaman suara adalah pilihan; kamera tidak digunakan.</strong></p><div class="btnrow"><button class="secondary" onclick="showAll=!showAll;render()">${showAll?'Lihat satu demi satu':'Lihat keempat-empat gambar'}</button><button class="secondary" onclick="showHelp=!showHelp;render()">${showHelp?'Sembunyikan bantuan':'💡 Bantuan bercerita'}</button></div>${showAll?`<div class="storyframes">${d.pictures.map((pic,i)=>frameHtml(pic,i,d)).join('')}</div>`:frameHtml(d.pictures[storyFrame],storyFrame,d)+`<div class="btnrow"><button class="secondary" onclick="storyFrame=Math.max(0,storyFrame-1);render()" ${storyFrame===0?'disabled':''}>← Sebelum</button><button class="secondary" onclick="storyFrame=Math.min(3,storyFrame+1);render()" ${storyFrame===3?'disabled':''}>Seterusnya →</button></div>`}${showHelp?`<div class="hint"><strong>Soalan panduan:</strong><ul>${d.q.map(q=>`<li>${esc(q)}</li>`).join('')}</ul><p>Contoh dialog ringkas boleh ditambah oleh guru. Murid tidak perlu membaca skrip untuk bercerita.</p></div>`:''}<div class="tile"><h2>🎭 Avatar Pencerita</h2><div class="avatar ${talking?'talking':''}" aria-label="Avatar ${session?.avatar||'panda'}">${ANIMALS[session?.avatar]||'🐼'}</div><p>${talking?'Avatar sedang bergerak seolah-olah bercakap. Ceritakan secara langsung.':'Tekan Mula Bercerita apabila bersedia.'}</p><div class="btnrow"><button onclick="startTalk()" ${talking?'disabled':''}>▶ Mula Bercerita</button><button class="secondary" onclick="finishTalk()" ${!talking?'disabled':''}>✓ Selesai Bercerita</button></div><p class="small muted">Animasi sahaja. Tiada mikrofon, kamera atau audio disimpan. Guru boleh mendengar dan menilai secara langsung.</p></div><div class="btnrow"><button class="secondary" onclick="navTo('loka')">← Kembali ke Loka</button><button onclick="navTo('passport')">📔 Lihat Pasport</button></div></section>`;}
function frameHtml(pic,i,d){return `<div class="frame"><div><div class="emoji">${pic}</div><strong>Gambar ${i+1}</strong><p class="small">${esc(d.q[i])}</p>${showHelp?`<button class="secondary" onclick="speakFrameQuestion(${i})">🔊 Dengar soalan</button>`:''}</div></div>`;}
function startTalk(){talking=true;render();}
async function finishTalk(){talking=false;storyDone=true;const p=await persist();render();if(p?.completed)notify('🎉 Loka lengkap! Cop pasport dan gula kapas telah diperoleh.');else notify('Penceritaan ditandakan selesai. Lengkapkan susunan ayat dan fasa SIMPUL untuk mendapat cop.');}
function passportHtml(){if(!session)return `<section class="panel"><h1>📔 Pasport</h1><p>Dapatkan Tiket Pengembaraan terlebih dahulu.</p><button onclick="navTo('home')">Ke Gerbang</button></section>`;const done=Object.values(progress).filter(p=>p.completed).length;return `<section class="panel passport"><div class="eyebrow">Pasport Pengembaraan</div><h1>📔 PASPORT SIMPULLOKA</h1><p>Pengembara: <strong>${esc(session.nickname)}</strong> ${ANIMALS[session.avatar]||'🐼'}<br><span class="small">Kelas: ${esc(session.kelas||'—')} · ID: ${esc(session.studentId)}</span></p><div class="grid">${IDIOMS.map((d,i)=>`<div class="stamp ${progress[i+1]?.completed?'done':''}"><div><div class="emoji">${progress[i+1]?.completed?d.icon:'🔒'}</div><strong>${d.name}</strong><br><span class="small">${progress[i+1]?.completed?'✓ COP SAH':'Belum dicop'}</span>${progress[i+1]?.completed?`<p class="small">${d.meaning}</p>`:''}</div></div>`).join('')}</div><div class="tile" style="margin-top:20px"><h2>🍭 Gerai Gula Kapas</h2><div class="giftline">${COTTON.map((x,i)=>`<div class="gift ${progress[i+1]?.completed?'':'locked'}"><div class="symbol">${progress[i+1]?.completed?x.icon:'🔒'}</div><small>${x.name}</small></div>`).join('')}</div><p>${done} daripada 6 gula kapas dikumpul</p></div>${done===6?`<div class="tile"><h2>🏆 Sijil Master SimpulLoka</h2><p>Tahniah, ${esc(session.nickname)}! Anda telah melengkapkan enam Loka.</p><button onclick="window.print()">🖨️ Cetak sijil / Simpan PDF</button></div>`:''}<div class="btnrow no-print"><button onclick="navTo('reflection')">🌈 Pentas Refleksi →</button><button class="secondary" onclick="navTo('wheel')">🎡 Kembali ke Roda Ferris</button></div></section>`;}
function reflectionHtml(){if(!session)return `<section class="panel"><h1>🌈 Pentas Refleksi</h1><p>Dapatkan tiket dahulu.</p><button onclick="navTo('home')">Ke Gerbang</button></section>`;
const feelings=[['gembira','😄'],['sedih','😢'],['kecewa','😞'],['tenang','😌'],['teruja','🤩']];return `<section class="panel"><div class="eyebrow">Selepas Pengembaraan</div><h1>🌈 Pentas Refleksi</h1><p>Semua perasaan boleh dikongsi. Tiada jawapan salah.</p><h2>Bagaimanakah perasaan kamu?</h2><div class="feelings">${feelings.map(([v,e])=>`<button class="${reflectionFeeling===v?'chosen':''}" onclick="chooseFeeling('${v}')">${e} ${v}</button>`).join('')}</div><h2>Apakah yang kamu pelajari?</h2><textarea class="field" id="learning" rows="4" maxlength="500" placeholder="Contoh: Saya belajar maksud simpulan bahasa ambil hati...">${esc(reflectionLearning)}</textarea><p class="small">Ayat bantuan: Hari ini saya belajar bahawa ...</p><div class="btnrow"><button onclick="saveReflectionNow()">💾 Simpan Refleksi</button></div><div class="grid"><div class="tile"><h2>🌱 Latihan Pemulihan</h2><p>Padankan simpulan bahasa dengan maksud melalui pilihan mudah.</p><button onclick="navTo('recovery')">Buka Pemulihan →</button></div><div class="tile"><h2>🚀 Latihan Pengukuhan</h2><p>Pilih simpulan bahasa berdasarkan situasi baharu.</p><button onclick="navTo('reinforcement')">Buka Pengukuhan →</button></div></div><div class="btnrow"><button class="secondary" onclick="navTo('passport')">← Pasport</button><button class="secondary" onclick="navTo('wheel')">🎡 Roda Ferris</button></div></section>`;}
function chooseFeeling(f){reflectionLearning=el('learning')?.value||reflectionLearning;reflectionFeeling=f;render();}
async function saveReflectionNow(){if(!session){notify('Sila dapatkan tiket dahulu.');return;}reflectionLearning=el('learning')?.value.trim()||'';if(!reflectionFeeling){notify('Pilih perasaan kamu dahulu.');return;}if(reflectionLearning.length<3){notify('Tuliskan apa yang kamu pelajari.');return;}try{reflection=await call('saveReflection',session.studentId,session.token,reflectionFeeling,reflectionLearning,recoveryDone,reinforcementDone);notify('Refleksi berjaya disimpan.');}catch(e){notify('Refleksi belum dapat disimpan: '+e.message);}}
const EXERCISES=[
 {idiom:'Dalam Tangan',question:'Hadiah itu sudah pasti akan diterima oleh Aina.',answer:0,choices:['Dalam Tangan','Air Muka','Cakap Besar']},
 {idiom:'Ambil Hati',question:'Aiman membantu ibunya supaya ibunya gembira.',answer:1,choices:['Mandi Peluh','Ambil Hati','Anak Emas']},
 {idiom:'Anak Emas',question:'Murid itu paling disayangi oleh jurulatih.',answer:2,choices:['Air Muka','Cakap Besar','Anak Emas']},
 {idiom:'Air Muka',question:'Wajah Farah berubah apabila mendengar berita itu.',answer:0,choices:['Air Muka','Dalam Tangan','Mandi Peluh']},
 {idiom:'Mandi Peluh',question:'Mereka berpeluh dengan banyak selepas bekerja keras.',answer:1,choices:['Ambil Hati','Mandi Peluh','Cakap Besar']},
 {idiom:'Cakap Besar',question:'Dia suka bermegah-megah tentang kehebatannya.',answer:2,choices:['Anak Emas','Air Muka','Cakap Besar']}
];
const REINFORCEMENT=[
 {question:'Aina sudah diumumkan sebagai pemenang. Hadiah itu kini ...',choices:['dalam tangan','mandi peluh','air muka'],answer:0},
 {question:'Amir membantu nenek untuk ... neneknya.',choices:['cakap besar','ambil hati','anak emas'],answer:1},
 {question:'Pemain itu sering diberi perhatian istimewa dan dianggap ... jurulatih.',choices:['air muka','dalam tangan','anak emas'],answer:2},
 {question:'... Lina berubah daripada takut kepada gembira.',choices:['Air muka','Mandi peluh','Cakap besar'],answer:0},
 {question:'Pekerja taman tema ... selepas mengangkat banyak barang.',choices:['ambil hati','mandi peluh','anak emas'],answer:1},
 {question:'Hakim suka ... tentang kebolehannya, walaupun belum mencuba.',choices:['air muka','dalam tangan','cakap besar'],answer:2}
];
let recoveryIndex=0,reinforceIndex=0,recoveryAnswers=0,reinforceAnswers=0;
function exerciseHtml(mode){if(!session)return `<section class="panel"><h1>Latihan</h1><p>Dapatkan tiket dahulu.</p><button onclick="navTo('home')">Ke Gerbang</button></section>`;
const rec=mode==='recovery',i=rec?recoveryIndex:reinforceIndex,bank=rec?EXERCISES:REINFORCEMENT,item=bank[i],done=rec?recoveryDone:reinforcementDone;return `<section class="panel"><div class="eyebrow">Latihan ${rec?'Pemulihan':'Pengukuhan'}</div><h1>${rec?'🌱 Pemulihan':'🚀 Pengukuhan'}</h1><p>${rec?'Pilih simpulan bahasa yang sesuai dengan maksud atau situasi.':'Baca situasi baharu dan pilih simpulan bahasa yang paling tepat.'}</p><div class="tile"><p>Soalan ${i+1} daripada ${bank.length}</p><h2>${esc(item.question)}</h2><div class="grid">${item.choices.map((choice,j)=>`<button class="secondary" onclick="answerExercise('${mode}',${j})">${esc(choice)}</button>`).join('')}</div><p class="small">${done?'✓ Latihan pernah dilengkapkan. Kamu boleh ulang.':'Jawapan salah boleh dicuba semula tanpa penalti.'}</p></div><div class="btnrow"><button class="secondary" onclick="navTo('reflection')">← Refleksi</button><button class="secondary" onclick="navTo('wheel')">🎡 Roda Ferris</button></div></section>`;}
function recoveryHtml(){return exerciseHtml('recovery');}
function reinforcementHtml(){return exerciseHtml('reinforcement');}
async function answerExercise(mode,choice){const rec=mode==='recovery',i=rec?recoveryIndex:reinforceIndex,item=(rec?EXERCISES:REINFORCEMENT)[i];if(choice!==item.answer){blockedNext('Cuba lagi! Baca maksud dan fikirkan simpulan bahasa yang sesuai.');return;}
 if(rec){recoveryAnswers++;recoveryIndex++;}else{reinforceAnswers++;reinforceIndex++;}
 if((rec?recoveryIndex:reinforceIndex)>=(rec?EXERCISES:REINFORCEMENT).length){if(rec){recoveryDone=true;recoveryIndex=0;}else{reinforcementDone=true;reinforceIndex=0;}
  notify('🎉 Tahniah! Latihan telah selesai.');if(reflectionFeeling&&reflectionLearning){try{reflection=await call('saveReflection',session.studentId,session.token,reflectionFeeling,reflectionLearning,recoveryDone,reinforcementDone);}catch(e){notify('Latihan selesai, tetapi status belum disimpan: '+e.message);}}else{notify('Latihan selesai! Isi dan simpan refleksi supaya status latihan direkodkan.');}navTo('reflection');return;}
 notify('✓ Betul! Teruskan ke soalan seterusnya.');render();}
function teacherHtml(){return `<section class="panel"><div class="eyebrow">Ruang Guru</div><h1>👩‍🏫 Sudut Cikgu</h1><div class="grid"><div class="tile"><h3>🎯 Objektif</h3><p class="small">Memahami simpulan bahasa, menyusun urutan cerita dan bercerita secara lisan.</p></div><div class="tile"><h3>📚 SK / SP</h3><p class="small">Rujuk DSKP Bahasa Melayu Tahun 3 untuk memuktamadkan kod SK/SP sebelum PdP.</p></div><div class="tile"><h3>♿ Panduan Inklusif</h3><p class="small">Aktifkan Mod Inklusif, baca arahan secara audio, gunakan klik kad dan beri masa yang mencukupi.</p></div><div class="tile"><h3>📝 Rubrik</h3><p class="small">Nilai kefahaman, urutan cerita dan penceritaan secara langsung pada skala 1–4. Guru menentukan TP.</p></div></div><h2>🔐 Rekod PBD</h2><p class="small">Rekod guru memerlukan kata laluan yang disediakan dalam Script Properties. Jangan berikan kata laluan ini kepada murid.</p><label for="teacherPassword">Kata laluan guru</label><input class="field" id="teacherPassword" type="password" placeholder="Kata laluan guru"><div class="btnrow"><button onclick="loadTeacher()">Buka Dashboard Guru</button><button class="secondary" onclick="teacherPass='';teacherData=null;render()">Log Keluar</button></div><div id="teacherArea">${teacherData?teacherAreaHtml():''}</div></section>`;}
async function loadTeacher(){teacherPass=el('teacherPassword').value;if(!teacherPass){notify('Masukkan kata laluan guru.');return;}try{teacherData=await call('teacherDashboard',teacherPass);el('teacherArea').innerHTML=teacherAreaHtml();notify('Dashboard guru berjaya dibuka.');}catch(e){notify(e.message);}}
function teacherAreaHtml(){if(!teacherData)return '';const rows=teacherData.students.map(s=>{const p=teacherData.progress.filter(x=>x.studentId===s.studentId);return `<tr><td>${esc(s.studentId)}</td><td>${esc(s.nickname)}</td><td>${esc(s.kelas||'—')}</td><td>${p.filter(x=>x.completed===true||String(x.completed)==='true').length}/6</td><td>${p.reduce((n,x)=>n+(Number(x.attempts)||0),0)}</td><td>${esc(teacherData.reflections?.find(r=>r.studentId===s.studentId)?.feeling||'—')}</td><td><button class="secondary" onclick="selectTeacher('${esc(s.studentId)}')">Nilai</button></td></tr>`;}).join('');return `<div class="tile"><h3>📊 Ringkasan Kelas</h3><p>${teacherData.students.length} murid • ${teacherData.progress.filter(x=>x.completed===true||String(x.completed)==='true').length} Loka diselesaikan</p><button onclick="downloadCsv()">⬇️ Eksport Rekod CSV</button></div><div class="teacher-table"><table><thead><tr><th>ID</th><th>Nama</th><th>Kelas</th><th>Loka selesai</th><th>Jumlah cubaan</th><th>Refleksi</th><th>PBD</th></tr></thead><tbody>${rows||'<tr><td colspan="7">Belum ada murid.</td></tr>'}</tbody></table></div><div id="assessment">${teacherSelected?assessmentHtml():''}</div>`;}
function selectTeacher(id){teacherSelected=id;teacherLoka=1;el('assessment').innerHTML=assessmentHtml();}
function assessmentHtml(){const s=teacherData.students.find(x=>x.studentId===teacherSelected);if(!s)return '';return `<div class="tile" style="text-align:left"><h3>📝 Pentaksiran: ${esc(s.nickname)}</h3><label>Loka</label><select class="field" id="assLoka" onchange="teacherLoka=Number(this.value)">${IDIOMS.map((d,i)=>`<option value="${i+1}" ${teacherLoka===i+1?'selected':''}>${i+1}. ${d.name}</option>`).join('')}</select><div class="grid">${[['understanding','Kefahaman'],['sequencing','Urutan cerita'],['oral','Penceritaan lisan']].map(([key,name])=>`<label>${name}<select class="field" id="${key}">${[1,2,3,4].map(n=>`<option value="${n}">${n} / 4</option>`).join('')}</select></label>`).join('')}</div><label>Catatan guru</label><textarea class="field" id="teacherNote" rows="3" placeholder="Pemerhatian semasa aktiviti lisan..."></textarea><label>Tahap Penguasaan (pertimbangan profesional guru)</label><select class="field" id="tp">${[1,2,3,4,5,6].map(n=>`<option value="${n}">TP${n}</option>`).join('')}</select><button onclick="saveTeacherAssessment()">Simpan Pentaksiran PBD</button></div>`;}
async function saveTeacherAssessment(){try{await call('saveAssessment',teacherPass,teacherSelected,teacherLoka,Number(el('understanding').value),Number(el('sequencing').value),Number(el('oral').value),el('teacherNote').value,Number(el('tp').value));notify('Pentaksiran guru berjaya disimpan.');teacherData=await call('teacherDashboard',teacherPass);}catch(e){notify(e.message);}}
function downloadCsv(){if(!teacherData)return;const columns=['studentId','nickname','kelas','lokaId','idiom','attempts','hintLevel','gameCorrect','simpulDone','storyDone','completed','teacherTP','teacherNote','feeling','learning','recoveryDone','reinforcementDone'];const data=teacherData.progress.map(p=>{const s=teacherData.students.find(x=>x.studentId===p.studentId)||{};const a=teacherData.assessments.find(x=>x.studentId===p.studentId&&Number(x.lokaId)===Number(p.lokaId))||{};const r=teacherData.reflections?.find(x=>x.studentId===p.studentId)||{};return [p.studentId,s.nickname||'',s.kelas||'',p.lokaId,IDIOMS[Number(p.lokaId)-1]?.name||'',p.attempts,p.hintLevel,p.gameCorrect,p.simpulDone,p.storyDone,p.completed,a.teacherTP||'',a.teacherNote||'',r.feeling||'',r.learning||'',r.recoveryDone||false,r.reinforcementDone||false];});const csv='\ufeff'+[columns,...data].map(r=>r.map(x=>'"'+String(x??'').replace(/^[=+@-]/,'\'$&').replace(/"/g,'""')+'"').join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='SimpulLoka_Rekod_PBD.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function initialize(){applyPref();if(session){try{const s=await call('getStudent',session.studentId,session.token);session.nickname=s.nickname;session.avatar=s.avatar;session.kelas=s.kelas||session.kelas||'';reflection=s.reflection||null;reflectionFeeling=reflection?.feeling||'';reflectionLearning=reflection?.learning||'';recoveryDone=reflection?.recoveryDone===true||String(reflection?.recoveryDone)==='true';reinforcementDone=reflection?.reinforcementDone===true||String(reflection?.reinforcementDone)==='true';progress=Object.fromEntries(s.progress.map(p=>[Number(p.lokaId),{...p,gameCorrect:p.gameCorrect===true||String(p.gameCorrect)==='true',simpulDone:p.simpulDone===true||String(p.simpulDone)==='true',storyDone:p.storyDone===true||String(p.storyDone)==='true',completed:p.completed===true||String(p.completed)==='true'}]));}catch(e){notify('Sesi lama tidak dapat dipulihkan: '+e.message);session=null;localStorage.removeItem(SimpulBackend.sessionKey);}}render();}
/* SIMPULLOKA V9 ADDITIONS — original V8.1 functions remain intact. */
const V9_SK='SK 4.1 — Mengaplikasikan unsur keindahan dan kesantunan bahasa dalam bahan sastera.';
